"""Pack the UI TTF into the application image and emit its integrity data."""

import pathlib
import sys
import zlib


def fnv1a(data: bytes) -> int:
    value = 0x811C9DC5
    for byte in data:
        value = ((value ^ byte) * 0x01000193) & 0xFFFFFFFF
    return value


def main() -> None:
    source, packed_path, header_path = map(pathlib.Path, sys.argv[1:])
    data = source.read_bytes()
    packed = zlib.compress(data, 9)
    header = (
        "/* Generated by tools/pack_font.py; do not edit. */\n"
        f"#define HA_UI_FONT_SIZE {len(data)}u\n"
        f"#define HA_UI_FONT_FNV1A 0x{fnv1a(data):08x}u\n"
    ).encode("ascii")
    for path, contents in ((packed_path, packed), (header_path, header)):
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists() or path.read_bytes() != contents:
            path.write_bytes(contents)


if __name__ == "__main__":
    main()
